      SUBROUTINE ELMDEFC---- DECODE ELEMENT DEFINITIONC-----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'AHORN.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1E.CIN'      INCLUDE 'DBEAM.CIN'      INCLUDE 'DBEND.CIN'      INCLUDE 'DCENT.CIN'      INCLUDE 'DCORR.CIN'      INCLUDE 'DCVTY.CIN'      INCLUDE 'DDRFT.CIN'      INCLUDE 'DETA.CIN'      INCLUDE 'DFIT.CIN'      INCLUDE 'DHKICK.CIN'      INCLUDE 'DHORN.CIN'      INCLUDE 'DKICK.CIN'      INCLUDE 'DMAGNE.CIN'      INCLUDE 'DMARK.CIN'      INCLUDE 'DMIS.CIN'      INCLUDE 'DMTX.CIN'      INCLUDE 'DOCT.CIN'      INCLUDE 'DORD.CIN'      INCLUDE 'DPLT.CIN'      INCLUDE 'DPRNT.CIN'      INCLUDE 'DQUAD.CIN'      INCLUDE 'DRAN.CIN'      INCLUDE 'DRBND.CIN'      INCLUDE 'DREPS.CIN'      INCLUDE 'DROT.CIN'      INCLUDE 'DSECT.CIN'      INCLUDE 'DSEPM.CIN'      INCLUDE 'DSEXT.CIN'      INCLUDE 'DSHIFT.CIN'      INCLUDE 'DSOLE.CIN'      INCLUDE 'DSPEC.CIN'      INCLUDE 'DSROT.CIN'      INCLUDE 'DSTRA.CIN'      INCLUDE 'DUNIT.CIN'      INCLUDE 'DUPD.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'HORNS.CIN'      INCLUDE 'ICODE.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'KELEM.CIN'      INCLUDE 'LBDAT.CIN'      INCLUDE 'NDICT.CIN'      INCLUDE 'NELMS.CIN'      INCLUDE 'NELMEQ.CIN'      INCLUDE 'NFLAGS.CIN'      INCLUDE 'NHORN.CIN'      INCLUDE 'NPLIN.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARLOC.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDHIST.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'RHORN.CIN'      INCLUDE 'RNTYPE.CIN'      INCLUDE 'THIKNS.CIN'      INCLUDE 'UROT.CIN'      INCLUDE 'VCODE.CIN'      INCLUDE 'ZHORN.CIN'C-----------------------------------------------------------------------      CHARACTER*15    DHIST(23), DFLAG(13), DDCAY(4)      CHARACTER*15    DLIM(3)      INTEGER         IDATA, IPDATA, IROW      INTEGER         J, JBEG, JDEF, JEND, JJ, JPAR, JPARS, J1, J2      INTEGER         KK, LAKE, LLOC      LOGICAL         CORREC, LTWISS      REAL            DIST, DPAR, FAKE      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATA, IPDATAC-----------------------------------------------------------------------      DATA NCBEAM /8/, NCROT  /1/, NCDRFT /1/, NCBEND /3/, NCQUAD /3/,     1     NCUPD  /4/, NCCENT /6/, NCMIS  /7/, NCREPS  /1/, NCFIT  /4/,     2     NCCVTY /4/, NCCORR /15/,            NCMTX  /86/, NCUNIT /2/,     3     NCSPEC /3/, NCORD  /2/, NCSEXT /3/, NCSOLE /2/, NCSROT /1/,     4     NCSTRA /3/,                         NCSECT /1/, NCOCT  /3/     5     NCRAN  /1/, NCETA  /6/, NCRBND /11/,            NCMARK /1/,     6     NCHKCK /2/,             NCPLT  /20/, NCLIM /2/, NCMAGN /3/,     7     NCSEPM /3/, NCSHFT /6/, NCHIST /5/, NCFLAG /4/,      8     NCDCAY /4/, NCKICK /3/, NCHORN /1/C-----------------------------------------------------------------------      DATA DLIM ( 1)    / 'LOWER   ' /      DATA DLIM ( 2)    / 'UPPER   ' /      DATA DLIM ( 3)    / 'ABSOLUTE' /C-----------------------------------------------------------------------      DATA DHIST( 1)    / 'NCOOR   ' /      DATA DHIST( 2)    / 'LOWER   ' /      DATA DHIST( 3)    / 'UPPER   ' /      DATA DHIST( 4)    / 'STEP' /      DATA DHIST( 5)    / 'NAME    ' /      DATA DHIST( 6)    / 'LOCATION' /      DATA DHIST( 7)    / 'X       ' /      DATA DHIST( 8)    / 'XP      ' /      DATA DHIST( 9)    / 'Y       ' /      DATA DHIST(10)    / 'YP      ' /      DATA DHIST(11)    / 'DL      ' /      DATA DHIST(12)    / 'DEL     ' /      DATA DHIST(13)    / 'L       ' /      DATA DHIST(14)    / 'P       ' /      DATA DHIST(15)    / 'COST    ' /      DATA DHIST(16)    / 'LD      ' /      DATA DHIST(17)    / 'R       ' /      DATA DHIST(18)    / 'XI      ' /      DATA DHIST(19)    / 'PSI     ' /      DATA DHIST(20)    / 'ZETA    ' /      DATA DHIST(21)    / 'PARENT  ' /      DATA DHIST(22)    / 'DAUGHTER1' /      DATA DHIST(23)    / 'DAUGHTER2' /C-----------------------------------------------------------------------      DATA DFLAG( 1)    / 'NCOOR   ' /      DATA DFLAG( 2)    / 'HWIDTH  ' /      DATA DFLAG( 3)    / 'IFLAG   ' /      DATA DFLAG( 4)    / 'LOCATION' /      DATA DFLAG( 5)    / 'X       ' /      DATA DFLAG( 6)    / 'XP      ' /      DATA DFLAG( 7)    / 'Y       ' /      DATA DFLAG( 8)    / 'YP      ' /      DATA DFLAG( 9)    / 'DL      ' /      DATA DFLAG(10)    / 'DEL     ' /      DATA DFLAG(11)    / 'PARENT  ' /      DATA DFLAG(12)    / 'DAUGHTER1' /      DATA DFLAG(13)    / 'DAUGHTER2' /C-----------------------------------------------------------------------      DATA DDCAY( 1)    / 'MASS    ' /      DATA DDCAY( 2)    / 'MASSC   ' /      DATA DDCAY( 3)    / 'MASSN   ' /      DATA DDCAY( 4)    / 'LIFETIME' /C-----------------------------------------------------------------------CC---- SWITCH ON ELEMENT TYPEC       IF (NTYPE .EQ. 53) GO TO 5300      IF (NTYPE .EQ. 60) GO TO 5500      IF (NTYPE .GE. 50) GO TO 5000      GO TO ( 100, 200, 300, 400, 500, 600, 700, 800, 900,1000,     1       1100,1200,6000,1400,1500,1600,1700,1800,1900,2000,     2       2100,6000,6000,2400,2500,2600,2700,2800,2900,6000,     3       3100,6000,6000,3400,3500,3600,3700,3800,3900,4000,     4       4100,4200,4300,4400,4500,4600,4600,4600), NTYPECC---- "BEAM" --- BEAM MATRIX AND MOMENTUMC  100 CALL DECPAR(NBEAM,DBEAM,NCBEAM,NPLIN,NBEAM)      IF (ENDFIL) GO TO 6000      IF (INDS .EQ. 0 .OR. INSERT) THEN        LTWISS = IPTYP(10) .NE. 0 .OR. IPTYP(13) .NE. 0        IF (.NOT. LTWISS) THEN          DO 120 J = 1, 6          IF (IPTYP(J) .EQ. 0) THEN            IPTYP(J) = 1            PDATA(J) = 0.0          ENDIF  120     CONTINUE        ELSE                IF (IPTYP(11) .EQ. 0) THEN            IPTYP(11) = 1            PDATA(11) = 0.0          ENDIF          IF (IPTYP(14) .EQ. 0) THEN            IPTYP(14) = 1            PDATA(14) = 0.0          ENDIF        ENDIF        IF (IPTYP(7) .EQ. 0) THEN          IPTYP(7) = 1          PDATA(7) = 0.0        ENDIF      ENDIF      NCPARA = 7      IF (IPTYP(19) .NE. 0) THEN        IPTYP(5) = 1        PDATA(5) = PDATA(19)        IPTYP(19) = 0        PDATA(19) = 0.0      ENDIF      GO TO 6000CC---- "ROTATION" --- POLE FACE ROTATIONC  200 CALL DECPAR(NROT,DROT,NCROT,NPLIN,NROT)      GO TO 6000CC---- "DRIFT" --- DRIFT SPACEC---- "ELSEP" --- ELECTROSTATIC SEPARATORC---- "ECOLLIMA" --- ELLIPTIC COLLIMATORC---- "RCOLLIMA" --- RECTANGULAR COLLIMATORC  300 CALL DECPAR(NDRFT,DDRFT,NCDRFT,NPLIN,NDRFT)      GO TO 6000CC---- "BEND" --- BENDING MAGNET WITHOUT FRINGING FIELDSC  400 CALL DECPAR(NBEND,DBEND,NCBEND,NPBEND,NBEND)      GO TO 6000CC---- "QUADRUPO" --- QUADRUPOLEC  500 CALL DECPAR(NQUAD,DQUAD,NCQUAD,NPLIN,NQUAD)      IF (ENDFIL) GO TO 6000      NTILT = 6      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.25*PI/UROT      ENDIF      GO TO 6000CC---- "UPDATE" --- UPDATE OF TRANSFER MATRIXC  600 CALL DECPAR(NUPD,DUPD,NCUPD,NPUPD,NUPD)      IF (ENDFIL) GO TO 6000      IF (IPTYP(1) .EQ. 0 .AND. IPTYP(4) .EQ. -2) THEN        IPTYP(1) = 1        IPTYP(2) = 1        IPTYP(4) = 0        PDATA(1) = 0.0        PDATA(2) = 1.0      ENDIF      IF (IPTYP(1) .EQ. 0 .AND. IPTYP(5) .EQ. -2) THEN        IPTYP(1) = 1        IPTYP(2) = 1        IPTYP(5) = 0        PDATA(1) = 0.0        PDATA(2) = 2.0      ENDIF      IF (IPTYP(1) .EQ. 0) THEN        IPTYP(1) = 1        PDATA(1) = 0.0      ENDIF      IF (IPTYP(2) .EQ. 0) THEN        IPTYP(2) = 1        PDATA(1) = 0.0      ENDIFC      DO 610 J = 1, 6      JP7 = J + 7      IF (IPTYP(JP7) .NE. 0) THEN        IPTYP(1) = 1        PDATA(1) = FLOAT(J)        IPTYP(JP7) = 0      ENDIF  610 CONTINUEC      IF (PDATA(1) .EQ. 0.0) THEN        IF (LDATA .NE. BLANK) THEN          CALL FNDELM(LDATA,NLOC,31)          LLOC = ISTOR(NLOC) + 1          IPTYP(3) = 1          LAKE = IDATA(LLOC)          PDATA(3) = FAKE          IPDAT(3) = 101        ENDIF        IPTYP(4) = 1        PDATA(4) = 0.0      ENDIF      GO TO 6000CC---- "CENTROID" -- BEAM CENTROID SHIFTC  700 CALL DECPAR(NCENT,DCENT,NCCENT,NPLIN,NCENT)      FILLIT = .TRUE.      GO TO 6000CC---- "MISALIGN" -- MAGNET MISALIGNMENTC  800 CALL DECPAR(NMIS,DMIS,NCMIS,NPLIN,NMIS)      IF (ENDFIL) GO TO 6000      CALL CODEIT      IF (INDS .EQ. 0 .OR. INSERT) THEN        DO 810 J = 1, 8        IF (IPTYP(J) .EQ. 0) THEN          IPTYP(J) = 1          PDATA(J) = 0.0        ENDIF  810   CONTINUE      ENDIF      IF (LDATA .NE. BLANK) THEN        CALL FNDELM(LDATA,NLOC,31)        LLOC = ISTOR(NLOC) + 1        IPTYP(9) = 1        LAKE = IDATA(LLOC)        PDATA(9) = FAKE        IPDAT(9) = 101      ENDIF      GO TO 6000CC---- "REPEAT" --- REPEAT A GIVEN SECTION OF BEAM LINEC  900 CALL DECPAR(NREPS,DREPS,NCREPS,NPLIN,NREPS)      LAKE = INT(PDATA(1))      PDATA(1) = FAKE      FILLIT = .TRUE.      GO TO 6000CC---- "FIT" --- FITTING CONSTRAINTSC 1000 CALL DECPAR(NFIT,DFIT,NCFIT,NPLIN,NFIT)      IF (ENDFIL) GO TO 6000      IF (VCODE(2) .EQ. 21) VCODE(2) = 1      IF (VCODE(2) .EQ. 30) VCODE(2) = 2      IF (IPTYP(8) .NE. 0) THEN        VCODE(2) = 1        IPTYP(8) = 0      ENDIF      IF (IPTYP(9) .NE. 0) THEN        VCODE(2) = 2        IPTYP(9) = 0      ENDIF      IF (IPTYP(1) .NE. 0) THEN        LAKE = INT(PDATA(1))        PDATA(1) = FAKE      ENDIF      IF (IPTYP(2) .NE. 0) THEN        LAKE = INT(PDATA(2))        PDATA(2) = FAKE      ENDIF      IF (IOPERS(5) .NE. 0 .OR. IPTYP(5) .EQ. 3) THEN        LAKE = 9        PDATA(1) = FAKE        PDATA(2) = PDATA(5)        IPTYP(1) = 1        IPTYP(2) = 1        IPDAT(2) = 100      ENDIF      IF (IOPERS(5) .EQ. 0 .AND. IPTYP(5) .NE. 0) THEN        LAKE = ICODE        PDATA(1) = FAKE        IPTYP(1) = 1        LAKE = JCODE        PDATA(2) = FAKE        IPTYP(2) = 1      ENDIF      IPTYP(5) = 0      IF (INDS .NE. 0) GO TO 6000      IPTYP(10) = 1      PDATA(10) = 0.0      IPTYP(11) = 1      PDATA(11) = 0.0      IF (LDATA .NE. BLANK .AND. .NOT. FLUSHL) THEN        CALL FNDELM(LDATA,NLOC,31)        IF (NLOC .EQ. 0) THEN          WRITE (NOUT,9651)  9651     FORMAT (' *** ERROR *** MARKER ELEMENT NOT FOUND')          FLUSHL = .TRUE.          GO TO 6000        ENDIF        LLOC = ISTOR(NLOC) + 1        IPTYP(7) = 1        PDATA(7) = DATA(LLOC)      ENDIF      FILLIT = .TRUE.      GO TO 6000CC---- "RF" --- RF CAVITYC 1100 CALL DECPAR(NCVTY,DCVTY,NCCVTY,NPLIN,NCVTY)      GO TO 6000CC---- "CORRELAT" --- CORRELATIONS IN BEAM ELLIPSEC 1200 CALL DECPAR(NCORR,DCORR,NCCORR,NPLIN,NCORR)      FILLIT = .TRUE.      GO TO 6000CC---- "MATRIX" --- ARBITRARY MATRIXC 1400 CALL DECPAR(NMTX,DMTX,NCMTX,NPLIN,NMTX)      IF (ENDFIL) GO TO 6000      NCPARA = 7      IF (IPTYP(8) .EQ. 1 .AND. PDATA(8) .EQ. 0.0) NCPARA = 29      IF (IPTYP(30) .EQ. 1 .AND. PDATA(30) .EQ. 0.0) NCPARA = 86      IROW = IFIX(PDATA(7))      IF (IPTYP(IROW) .NE. 1) THEN        PDATA(IROW) = 1.0        IPTYP(IROW) = 1      ENDIF      FILLIT = .TRUE.      GO TO 6000CC---- "UNITS" --- UNITS CHANGEC 1500 CALL DECPAR(NUNIT,DUNIT,NCUNIT,NPLIN,NUNIT)      IF (ENDFIL) GO TO 6000      JJ = 0      JBEG = 9      JEND = 20      DO 1510 J = JBEG, JEND      JJ = JJ + 1      IF (JJ .EQ. 3) JJ = 5      IF (IPTYP(J) .NE. 0) THEN        IPTYP(J) = 0        IPTYP(1) = 1        PDATA(1) = FLOAT(JJ)        GO TO 1520      ENDIF 1510 CONTINUEC 1520 JBEG = 21      JEND = 39      DO 1530 J = JBEG, JEND      IF (IPTYP(J) .NE. 0) THEN        IPTYP(J) = 0        LABLE = DUNIT(J)        LBDAT = LABLE        GO TO 1540      ENDIF 1530 CONTINUEC 1540 IF (IPTYP(1) .EQ. 1 .AND. IPTYP(2) .EQ. 1) GO TO 6000      IF (IPTYP(1) .EQ. 1 .AND. LABLE .NE. BLANK) THEN        NWORD = 3        PDATA(2) = 0.0        IPTYP(2) = 1        GO TO 6000      ENDIF      IF (IPTYP(1) .EQ. 0) THEN        NWORD = 2        PDATA(1) = 0.0        IPTYP(1) = 1      ENDIF      IF (PDATA(1) .EQ. 0.0) THEN        LABLE = BLANK        GO TO 6000      ENDIFC      WRITE (NOUT, 9650) 9650 FORMAT ('0EARROR ON UNITS ELEMENT')      FLUSHL = .TRUE.      GO TO 6000CC---- "SPECIAL" --- SPECIAL PARAMETERSC 1600 CALL DECPAR(NSPEC,DSPEC,NCSPEC,NPLIN,NSPEC)      IF (ENDFIL) GO TO 6000      IF (IPTYP(1) .NE. 0) THEN        IF (PDATA(1) .LT. 0.0) THEN          NWORD = 4          GO TO 1640        ENDIF        ENDIF      NDO = NSPEC - 3      DO 1610 J = 4, NSPEC      IF (J .EQ. 38) GO TO 1610      IF (IPTYP(J) .NE. 0) THEN        JPAR = J        GO TO 1620      ENDIF 1610 CONTINUE      JPARS = INT(PDATA(1))      IF (IPTYP(2) .EQ. 0 .AND. JPARS .GE. 200     1    .AND. JPARS .LE. 202) THEN        IPTYP(2) = 1        IF (JPARS .EQ. 200) PDATA(2) = 1.0        IF (JPARS .EQ. 201) PDATA(2) = 1.0        IF (JPARS .EQ. 202) PDATA(2) = 0.0      ENDIF      GO TO 1630C 1620 NWORD = 3      JPARS = JPAR - 3      IF (JPAR .EQ. 31) JPARS = 100      IF (JPAR .EQ. 32) JPARS = 101      IF (JPAR .EQ. 33) JPARS = 102      IF (JPAR .EQ. 34) JPARS = 109      IF (JPAR .EQ. 35) JPARS = 200      IF (JPAR .EQ. 36) JPARS = 201      IF (JPAR .EQ. 37) JPARS = 202C      IPTYP(1) = 1      PDATA(1) = JPARS      IF (JPARS .GE. 200 .AND. JPARS .LE. 202) THEN         IF(IPTYP(38) .NE. 0) THEN          IPTYP(2) = IPTYP(38)          PDATA(2) = PDATA(38)          IPDAT(2) = IPDAT(38)        ELSE          IPTYP(2) = 1          IF (JPARS .EQ. 200) PDATA(2) = 1.0          IF (JPARS .EQ. 201) PDATA(2) = 1.0          IF (JPARS .EQ. 202) PDATA(2) = 0.0          IPDAT(2) = 0        ENDIF      ELSE        IPTYP(2) = IPTYP(JPAR)        PDATA(2) = PDATA(JPAR)        IPDAT(2) = IPDAT(JPAR)      ENDIF      IPTYP(JPAR) = 0C 1630 IF (JPARS .EQ. 200) THEN        DBEAM(19) = LBDAT        DUPD(14) = LBDAT         DPRNT(19) = LBDAT        DHIST(21) = LBDAT        DFLAG(11) = LBDAT      ENDIF      IF (JPARS .EQ. 201) THEN        DBEAM(20) = LBDAT        DUPD(15) = LBDAT         DPRNT(20) = LBDAT        DHIST(22) = LBDAT        DFLAG(12) = LBDAT      ENDIF      IF (JPARS .EQ. 202) THEN        DBEAM(21) = LBDAT        DUPD(16) = LBDAT         DPRNT(21) = LBDAT        DHIST(23) = LBDAT        DFLAG(13) = LBDAT      ENDIF 1640 DO 1650 J = 1, 2 1650 CONTINUE         GO TO 6000CC---- "ORDER" --- HIGHER ORDER CALCULATIONC 1700 CALL DECPAR(NORD,DORD,NCORD,NPLIN,NORD)      IF (ENDFIL) GO TO 6000      IF (IPTYP(3) .NE. 0) THEN        IPTYP(1) = IPTYP(3)        PDATA(1) = PDATA(3)        IPTYP(2) = IPTYP(1)        PDATA(2) = PDATA(1)        IPTYP(3) = 0        PDATA(3) = 0.0      ENDIF      IF (INDS .EQ. 0 .OR. INSERT) THEN        IF (IPTYP(1) .EQ. 0) THEN          IPTYP(1) = 1          PDATA(1) = 2.0        ENDIF        IF (IPTYP(2) .EQ. 0) THEN          IPTYP(2) = 1          PDATA(2) = PDATA(1)        ENDIF      ENDIF      GO TO 6000CC---- "SEXTUPOL" --- SEXTUPOLEC 1800 CALL DECPAR(NSEXT,DSEXT,NCSEXT,NPLIN,NSEXT)      NTILT = 5      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = PI/(6.0*UROT)      ENDIF      GO TO 6000CC---- "SOLENOID" --- SOLENOIDC 1900 CALL DECPAR(NSOLE,DSOLE,NCSOLE,NPLIN,NSOLE)      GO TO 6000CC---- "SROT" --- ROTATE AROUND LONGITUDINAL AXISC 2000 CALL DECPAR(NSROT,DSROT,NCSROT,NPLIN,NSROT)      GO TO 6000CC---- "STRAY" --- STRAY FIELDC 2100 CALL DECPAR(NSTRA,DSTRA,NCSTRA,NPLIN,NSTRA)      GO TO 6000CC---- "SECTION" -- DEFINED SECTIONC 2400 CALL DECPAR(NSECT,DSECT,NCSECT,NPLIN,NSECT)      IF (ENDFIL) GO TO 6000      NWORD = 2      LAKE = INT(PDATA(1))      PDATA(1) = FAKE      DO 2410 J = 2, 5      IF (IPTYP(J) .EQ. -2) THEN        LAKE = J - 1        PDATA(1) = FAKE        IPTYP(1) = 1        IPTYP(J) = 0      ENDIF 2410 CONTINUE      JDEF = IPDATA(1)      IF (JDEF .GE. 3) THEN        NWORD = 4        IPTYP(2) = 100        IPTYP(3) = 100      ENDIF      GO TO 6000CC---- "OCTUPOLE" --- OCTUPOLEC 2500 CALL DECPAR(NOCT,DOCT,NCOCT,NPLIN,NOCT)      NTILT = 5      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.125*PI/UROT      ENDIF      GO TO 6000CC---- "RANDOM" --- RANDOM ALTERATIONS TO PHYSICAL PARAMETERSC 2600 CALL DECPAR(NELEM,KELEM,NCRAN,NPLIN,1)      IF (ENDFIL) GO TO 6000      IF (IPTYP(1) .NE. 0) THEN        TYPER = INT(PDATA(1))        IPTYP(1) = 0      ELSE        DO 2605 J = 1, NELEM        IF (IPTYP(J) .EQ. 0) GO TO 2605        TYPER = J        IPTYP(J) = 0        GO TO 2610 2605   CONTINUE      ENDIFC 2610 IF (TYPER .EQ. 16) GO TO 6000      CALL ELMPAR      IF (ENDFIL) GO TO 6000      NPARS = NELMS(TYPER)      DO 2615 J = 1, NPARS      IF (IPTYP(J) .EQ. 0) GO TO 2615      NPAR = J      GO TO 2620 2615 CONTINUEC 2620 CALL DECPAR(NRAN,DRAN,NCRAN,NPLIN,1)      DPAR = PDATA(1)C      PDATA(1) = TYPER      PDATA(2) = NPAR      PDATA(3) = DPAR      IPTYP(1) = 1      IPTYP(2) = 1      IPTYP(3) = 1      GO TO 6000CC---- "ETA" --- ACCELERATOR FUNCTION ETAC 2700 CALL DECPAR(NETA,DETA,NCETA,NPLIN,NETA)      IF (IPTYP(6) .EQ. 0) THEN        IPTYP(6) = 1        PDATA(6) = 1.0      ENDIF      FILLIT = .TRUE.      GO TO 6000CC---- "RBEND" --- RECTANGULAR BENDING MAGNETC 2800 CALL DECPAR(NRBND,DRBND,NCRBND,NPRBND,NRBND)      MADNO = .TRUE.      NTILT = 24      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.5*PI/UROT      ENDIF      GO TO 6000CC---- "SBEND" --- SECTOR BENDING MAGNETC 2900 CALL DECPAR(NRBND,DRBND,NCRBND,NPRBND,NRBND)      MADNO = .TRUE.      NTILT = 24      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.5*PI/UROT      ENDIF      GO TO 6000CC--- "MARKER" --- POSITION MARKERC 3100 CALL DECPAR(NMRKR,DMARK,NCMARK,NPLIN,NMRKR)      NMARKS = NMARKS + 1      IPTYP(1) = 1      LAKE = NMARKS      PDATA(1) = FAKE      GO TO 6000CC---- "PLASMALE" --- PLASMA LENSC 3400 CALL DECPAR(NQUAD,DQUAD,NCQUAD,NPLIN,NQUAD)      GO TO 6000CC ---- "HKICK" --- HORIZONTAL KICKC 3500 CALL DECPAR(NHKCK,DHKICK,NCHKCK,NPHKCK,NHKCK)      NTILT = 5      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.5*PI/UROT      ENDIF      GO TO 6000CC ---- "VKICK" --- VERTICAL KICKC 3600 CALL DECPAR(NHKCK,DHKICK,NCHKCK,NPHKCK,NHKCK)      NTILT = 5      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.5*PI/UROT      ENDIF      GO TO 6000CC---- "ALMARK" --- INDICATION OF BEGINNING OF MISALIGNED SECTIONC 3700 CALL DECPAR(NUPD,DUPD,NCUPD,NPLIN,NUPD)      IF (ENDFIL) GO TO 6000      IF (IPTYP(1) .EQ. 0 .AND. IPTYP(4) .EQ. -2) THEN        IPTYP(1) = 1        IPTYP(2) = 1        IPTYP(4) = 0        PDATA(1) = 0.0        PDATA(2) = 1.0      ENDIF      IF (IPTYP(1) .EQ. 0 .AND. IPTYP(5) .EQ. -2) THEN        IPTYP(1) = 1        IPTYP(2) = 1        IPTYP(5) = 0        PDATA(1) = 0.0        PDATA(2) = 2.0      ENDIF      IF (IPTYP(1) .EQ. 0) THEN        IPTYP(1) = 1        PDATA(1) = 0.0      ENDIF      IF (IPTYP(2) .EQ. 0) THEN        IPTYP(2) = 1        PDATA(1) = 0.0      ENDIF      IF (PDATA(1) .EQ. 0.0) THEN        IF (LDATA .NE. BLANK) THEN          CALL FNDELM(LDATA,NLOC,31)          LLOC = ISTOR(NLOC) + 1          IPTYP(3) = 1          LAKE = IDATA(LLOC)          PDATA(3) = FAKE          IPDAT(3) = 101        ENDIF        IPTYP(4) = 1        PDATA(4) = 0.0      ENDIF      GO TO 6000CC---- "PLOT" --- PLOTTING OF MATRIX ELEMENTSC 3800 CALL DECPAR(NPLT,DPLT,NCPLT,NPLIN,NPLT)      IF (ENDFIL) GO TO 6000      NKT = 0      DO 3810 J = 1, 20      IF (IPTYP(J) .NE. 0) THEN        NKT = NKT + 1        LAKE = INT(PDATA(J))        PDATA(J) = FAKE      ENDIF 3810 CONTINUEC      DO 3820 J = 1, 10      IF (IOPERS(J+20) .NE. 0 .OR. IPTYP(J+20) .EQ. 1     1    .OR. IPTYP(J+20) .EQ. 3) THEN        J1 = 2*J - 1        J2 = 2*J        NKT = MAX0(NKT,J2)        LAKE = 9        PDATA(J1) = FAKE        LAKE = IPDATA(J+20)        PDATA(J2) = FAKE        IPTYP(J1) = 1        IPTYP(J2) = 1        IPDAT(J2) = 100      ENDIF 3820 CONTINUEC      IF (IPTYP(3) .EQ. -2) IPTYP(3) = 1      IF (INDS .NE. 0) GO TO 6000      IF (LDATA .NE. BLANK) THEN        CALL FNDELM(LDATA,NLOC,31)        LLOC = ISTOR(NLOC) + 1        IPTYP(NKT+1) = 1        PDATA(NKT+1) = DATA(LLOC)        IPDAT(NKT+1) = 101      ENDIF      GO TO 6000CC ---- "LIMIT" --- LIMITS ON PHYSICAL PARAMETERS IN FITTINGC 3900 CALL DECPAR(NELEM,KELEM,NCRAN,NPLIN,1)      IF (ENDFIL) GO TO 6000      DO 3905 J = 1, NELEM      IF (IPTYP(J) .NE. 0) THEN        TYPER = J        IPTYP(J) = 0        GO TO 3910      ENDIF 3905 CONTINUEC 3910 IF (TYPER .EQ. 16) GO TO 6000      NTSAVE = NTYPE      NTYPE = TYPER      CALL ELMPAR      NTYPE = NTSAVE      IF (ENDFIL) GO TO 6000      IF (IPTYP(1) .GT. 0) THEN        NPAR = INT(PDATA(1))        IPTYP(1) = 0      ELSE        NDO = NELMS(TYPER)        DO 3915 J = 1, NDO        IF (IPTYP(J) .NE. 0) THEN          NPAR = J          IPTYP(J) = 0          GO TO 3920        ENDIF 3915   CONTINUE      ENDIFC 3920 IPTYP(1) = 0      IPTYP(2) = 0      IPTYP(3) = 0      CALL DECPAR(3,DLIM,NCLIM,NPLIN,3)      IF (IPTYP(3) .EQ. 1) THEN        IPTYP(5) = 1        PDATA(5) = PDATA(3)        IPTYP(3) = 0        PDATA(3) = 0.0      ENDIF      IF (IPTYP(2) .EQ. 1) THEN        IPTYP(4) = 1        PDATA(4) = PDATA(2)      ENDIF      IF (IPTYP(1) .EQ. 1) THEN        IPTYP(3) = 1        PDATA(3) = PDATA(1)      ENDIFC      PDATA(1) = TYPER      PDATA(2) = NPAR      IPTYP(1) = 1      IPTYP(2) = 1      GO TO 6000CC---- "MAGNET" --- GENERAL MAGNET DESCRIPTIONC 4000 CALL DECPAR(NMAGN,DMAGNE,NCMAGN,NPLIN,NMAGN)      GO TO 6000CC---- "SEPTUM" --- ELECTROSTATIC SEPTUMC 4100 CALL DECPAR(NSEPM,DSEPM,NCSEPM,NPLIN,NSEPM)      NTILT = 10      IF (IPTYP(NTILT) .EQ. -2) THEN        IPTYP(NTILT) = 1        PDATA(NTILT) = 0.5*PI/UROT      ENDIF      GO TO 6000CC ---- "KICKER" --- KICKER FOR BOTH PLANESC 4200 CALL DECPAR(NKICK,DKICK,NCKICK,NPLIN,NKICK)      GO TO 6000CC ---- "SHIFT" --- SHIFT IN THE REFERENCE COORDINATE SYSTEMC 4300 CALL DECPAR(NSHIFT,DSHIFT,NCSHFT,NPLIN,NSHIFT)      FILLIT = .TRUE.      GO TO 6000CC ---- "BROAD' --- BROAD BAND FITTINGC 4400 NCPARA = 0      GO TO 6000CC ---- "HORN" --- NEUTRINO HORNC 4500 CALL DECPAR(NPHORN,DHORN,NCHORN,NPLIN,NPHORN)      IF (ENDFIL) GO TO 6000      NHORN = NHORN + 1      N = NHORN      CORREC = .TRUE.      READ (5,1035) (ZHORN(N,J), J = 1, 12)      READ (5,1035) (RHORN(N,J), J = 1, 12)      READ (5,1035) (THIKNS(N,J), J = 1, 12)C      LASTH(N) = 0      IF (ABS(RHORN(N,1)) .LT. 0.0001) GO TO 6000      DO 4501 J = 2, MXHORN      IF (RHORN(N,J) .LT. 0.0001) GO TO 4502      LASTH(N) = J      DIST = ZHORN(N,J) - ZHORN(N,J-1)      IF (DIST .LT. 0.0) THEN        AHORN(N,J-1) = 0.0        CORREC = .FALSE.      ELSE        AHORN(N,J-1) = (RHORN(N,J) - RHORN(N,J-1))/DIST      ENDIF 4501 CONTINUEC 4502 KK = LASTH(N)      WRITE (NOUT,1036) (ZHORN(N,J), J = 1, KK)      WRITE (NOUT,1037) (RHORN(N,J), J = 1, KK)      KK = KK - 1      WRITE (NOUT,1038) (AHORN(N,J), J = 1, KK)      WRITE (NOUT,1039) (THIKNS(N,J), J = 1, KK) 1036 FORMAT (1H ,20X,'  Z = ',12F8.3) 1037 FORMAT (1H ,20X,'  R = ',12F8.3) 1038 FORMAT (21X,'  ANGLE = ',12F8.3) 1039 FORMAT (21X,' THIKNS = ',12F8.3)C      IF (.NOT. CORREC) THEN        WRITE (NOUT,1034)        NFAIL = NFAIL + 1      ENDIF      GO TO 6000CC---- "HMONITOR" --- HORIZONTAL MONITORC---- "VMONITOR" --- VERTICAL MONITORC---- "MONITOR" --- MONITOR FOR BOTH PLANESC 4600 CALL DECPAR(NDRFT,DDRFT,NCDRFT,NPLIN,NDRFT)      GO TO 6000CC ---- "HIST" --- HISTOGRAMC 5000 CALL DECPAR(NPHST,DHIST,NCHIST,NPLIN,NPHST)      IF (ENDFIL) GO TO 6000      NCPARA = 4      IF (IPTYP(1) .NE. 0) THEN        LAKE = INT(PDATA(1))        PDATA(1) = FAKE      ENDIFC      DO 5010 J = 1, 14      JP6 = J + 6      IF (IPTYP(JP6) .NE. 0) THEN        IPTYP(1) = 1        LAKE = J        IF (J .EQ. 7) LAKE = 8        IF (J .EQ. 8) LAKE = 11        IF (J .EQ. 9) LAKE = 12        IF (J .EQ. 10) LAKE = 18        IF (J .EQ. 11) LAKE = 21        IF (J .EQ. 12) LAKE = 22        IF (J .EQ. 13) LAKE = 23        IF (J .EQ. 14) LAKE = 24        PDATA(1) = FAKE        IPTYP(JP6) = 0      ENDIF 5010 CONTINUEC      DO 5020 J = 1, 3      IF (IPTYP(J+20) .NE. 0) THEN        FAKE = PDATA(1)        LAKE = 100*(J-1) + LAKE        PDATA(1) = FAKE      ENDIF   5020 CONTINUEC            IF (LDATA .NE. BLANK) THEN        CALL FNDELM(LDATA,NLOC,31)        IF (NLOC .EQ. 0) THEN          FLUSHL = .TRUE.          GO TO 6000        ENDIF        LLOC = ISTOR(NLOC) + 1        IPTYP(6) = 1        LAKE = IDATA(LLOC)        PDATA(6) = FAKE      ENDIFC      NI = VCODE(2) + 1      IF (VCODE(2) .NE. 0 .AND. LRDFLG .EQ. BLANK)     1    LRDFLG = 'FLAG'//NUMB(NI:NI)C      NHSTS = NHSTS + 1      LRFLAG(NHSTS) = LRDFLG      GO TO 6000CC ---- "FLAG" --- HISTOGRAM FLAGC 5300 CALL DECPAR(NPFLG,DFLAG,NCFLAG,NPLIN,NPFLG)      IF (ENDFIL) GO TO 6000      IF (LBDAT .EQ. BLANK .AND. VCODE(2) .EQ. 0) THEN        FLUSHL = .TRUE.        GO TO 6000      ENDIF      NFLAGS = NFLAGS + 1      NI = VCODE(2) + 1      IF (VCODE(2) .NE. 0 .AND. LBDAT .EQ. BLANK)      1    LBDAT = 'FLAG'//NUMB(NI:NI)      VCODE(2) = 0C      IF (IPTYP(1) .EQ. 0) THEN        IPTYP(1) = 1        PDATA(1) = 300.0      ENDIFC      DO 5310 J = 1, 6      JP4 = J + 4      IF (IPTYP(JP4) .NE. 0) THEN        PDATA(1) = PDATA(1) + FLOAT(J)      ENDIF 5310 CONTINUEC      DO 5320 J = 1, 3      JP10 = J + 10      IF (IPTYP(JP10) .NE. 0) THEN        JOLD = IFIX(PDATA(1))        JNEW = 100*(J-1) + MOD(JOLD,100)        PDATA(1) = FLOAT(JNEW)      ENDIF 5320 CONTINUEC      IF (IPTYP(2) .EQ. 0) THEN        IPTYP(2) = 1        PDATA(2) = 0.0      ENDIFC      IPTYP(3) = 1      LAKE = NFLAGS      PDATA(3) = FAKEC      IF (LDATA .NE. BLANK) THEN        CALL FNDELM(LDATA,NLOC,31)        LLOC = ISTOR(NLOC) + 1        IPTYP(4) = 1        LAKE = IDATA(LLOC)        PDATA(4) = FAKE      ENDIF      GO TO 6000CC ---- "DECAY" --- DECAY CALCULATIONC 5500 CALL DECPAR(NPDCAY,DDCAY,NCDCAY,NPLIN,NPDCAY)      FILLIT = .TRUE.      DO 5501 J = 1, 5 5501 CONTINUE      GO TO 6000CC---- IF ALL OK THEN DEFINE ELEMENTC 6000 CONTINUE      RETURNC-----------------------------------------------------------------------  910 FORMAT(' *** ERROR *** ELEMENT NAME EXPECTED'/' ')  920 FORMAT(' ** WARNING ** THE ABOVE NAME WAS DEFINED IN LINE ',I5,     +       ', IT WILL BE REDEFINED'/' ')  940 FORMAT(' ** WARNING ** ELEMENT NOT IMPLEMENTED --- ',     +       'TREATED LIKE A "DRIFT"'/' ')  950 FORMAT(' ** WARNING ** ELEMENT NOT IMPLEMENTED --- ',     +       'TREATED LIKE A "MARKER"'/' ')  960 FORMAT(' ** WARNING ** VALUE EXPECTED FOR PARAMETER "',     +       A,' ',A,' "'/' ') 1034 FORMAT ( 15H INCORRECT DATA ) 1035 FORMAT (12F5.0)C-----------------------------------------------------------------------      END